from functools import lru_cache


@lru_cache(maxsize=None)
def _g(rem, s, p):
    # p nonzero product so far; count completions of length rem that are beautiful
    if rem == 0:
        return 1 if p % s == 0 else 0
    total = 10 ** (rem - 1)  # digit 0 -> product zero -> always beautiful
    for d in range(1, 10):
        total += _g(rem - 1, s + d, p * d)
    return total


def _f(n):
    if n <= 0:
        return 0
    ds = [int(c) for c in str(n)]
    L = len(ds)
    total = 0
    for m in range(1, L):
        for d in range(1, 10):
            total += _g(m - 1, d, d)
    s, p = 0, 1
    for i, dig in enumerate(ds):
        rem = L - i - 1
        for d in range(1 if i == 0 else 0, dig):
            if d == 0:
                total += 10 ** rem
            else:
                total += _g(rem, s + d, p * d)
        if dig == 0:
            rest = int("".join(map(str, ds[i + 1:])) or "0")
            return total + rest + 1
        s += dig
        p *= dig
    if p % s == 0:
        total += 1
    return total


