from collections import deque


def _maxflow(N, adj_edges, s, t, limit):
    graph = [[] for _ in range(N)]
    to = []
    cap = []
    for a, b, c in adj_edges:
        graph[a].append(len(to)); to.append(b); cap.append(c)
        graph[b].append(len(to)); to.append(a); cap.append(0)
    flow = 0
    while flow <= limit:
        prev = [-1] * N
        prev[s] = -2
        dq = deque([s])
        while dq and prev[t] == -1:
            x = dq.popleft()
            for e in graph[x]:
                if cap[e] > 0 and prev[to[e]] == -1:
                    prev[to[e]] = e
                    dq.append(to[e])
        if prev[t] == -1:
            break
        # bottleneck
        f = float('inf')
        x = t
        while x != s:
            e = prev[x]
            f = min(f, cap[e])
            x = to[e ^ 1]
        x = t
        while x != s:
            e = prev[x]
            cap[e] -= f
            cap[e ^ 1] += f
            x = to[e ^ 1]
        flow += f
        if f == float('inf'):
            return float('inf')
    return flow


